"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["19298"],{13080(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.regras_padrao_so_em_derivado_por_regra","status":422,"titulo":"S\xf3 o fato derivado por regra tem regras padr\xe3o"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.regras_padrao_so_em_derivado_por_regra","requisitos":["UNI-REQ-0075","UNI-REQ-0143"],"oQueAconteceu":["O administrador enviou regras padr\xe3o (`PUT /api/configuracao/admin/fatos-candidato/{id}/regras-padrao`) para um fato declarado ou para um resumo de grupo. As regras padr\xe3o dizem como o valor de um fato derivado por regra \xe9 calculado a partir de outros fatos (UNI-REQ-0075). O fato declarado recebe a resposta de quem se inscreve, e o resumo de grupo re\xfane as respostas dos membros de um grupo, a partir do fato de membro, sem regra padr\xe3o.","As confer\xeancias seguem esta ordem: o fato ([fato do candidato n\xe3o encontrado](/erros/uniplus.configuracao.fato_candidato.nao_encontrado)), a recusa de fato de sistema ([defini\xe7\xe3o do fato de sistema travada](/erros/uniplus.configuracao.fato_candidato.definicao_do_fato_de_sistema_travada)) e, por \xfaltimo, esta. A resposta n\xe3o traz a lista `errors`. Nada \xe9 gravado."],"comoResolver":["Envie as regras para um fato derivado por regra. Se o valor que se quer calcular ainda n\xe3o tem fato, cadastre um fato derivado por regra, booleano ou categ\xf3rico (`POST /api/configuracao/admin/fatos-candidato/derivados`), e ent\xe3o defina as regras dele."],"ondeAparece":["Defini\xe7\xe3o das regras padr\xe3o de um fato derivado por regra"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);